window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[343]={"id":"343","numero":343,"titre":"État confusionnel et trouble de la conscience","objectifs":[{"id":"343-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome confusionnel","contenu":"<p>Le <span class=\"kw-def\">syndrome confusionnel</span> (état confusionnel, <em>delirium</em>) se définit comme une <span class=\"kw-def\">altération modérée de la vigilance</span> entraînant une <span class=\"kw-def\">désorganisation globale de la pensée</span> et un dysfonctionnement de l'ensemble des <span class=\"kw-def\">fonctions cognitives</span>. C'est un <span class=\"kw-clinique\">trouble attentionnel sévère</span>, d'installation <span class=\"kw-clinique\">aiguë ou subaiguë</span> et <span class=\"kw-clinique\">fluctuant</span>.</p>\n      <p><strong>Mécanisme conceptuel</strong> — l'<span class=\"kw-def\">attention</span> est la « porte d'entrée » ouvrant vers le fonctionnement de l'ensemble des fonctions cognitives :</p>\n      <ul>\n        <li>Si cette porte est « entrebâillée » ou « fermée », les fonctions intellectuelles qui en dépendent sont perturbées.</li>\n        <li>Séquence physiopathologique : <span class=\"kw-clinique\">altération de la vigilance</span> → <span class=\"kw-clinique\">troubles attentionnels</span> → <span class=\"kw-def\">confusion mentale</span>.</li>\n      </ul>\n      <p><strong>Définition selon les critères du DSM-5</strong> — cinq critères, de A à E :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>A — Attention</td><td><span class=\"kw-alerte\">Perturbation de l'attention</span> (diminution de la capacité à diriger, focaliser, soutenir et déplacer son attention) et de l'orientation — évaluation rapide : test d'orientation spatio-temporelle + épreuve attentionnelle (<em>jours de la semaine à l'envers</em>)</td></tr>\n          <tr><td>B — Installation</td><td>Installation sur un <span class=\"kw-chiffre\">temps court</span> (<span class=\"kw-chiffre\">quelques heures à quelques jours</span>) ; <span class=\"kw-alerte\">fluctuation en sévérité</span> au long de la journée ; <span class=\"kw-clinique\">rupture avec l'état antérieur</span>, établie par l'interrogatoire d'un proche ; identifier les formes hypo- et hyperactives</td></tr>\n          <tr><td>C — Cognition</td><td>Existence d'une <span class=\"kw-clinique\">autre perturbation cognitive</span> : mémoire, orientation, langage (au sens d'incohérence), habiletés visuo-spatiales ou perceptions</td></tr>\n          <tr><td>D — Exclusion</td><td>Critères A et C non mieux expliqués par un <span class=\"kw-def\">trouble neurocognitif préexistant</span>, et hors contexte d'une <span class=\"kw-alerte\">vigilance très réduite</span> (<span class=\"kw-alerte\">coma</span>)</td></tr>\n          <tr><td>E — Étiologie</td><td>Perturbation = conséquence directe d'une <span class=\"kw-alerte\">affection médicale</span>, d'une intoxication, d'un <span class=\"kw-ttt\">sevrage</span> (<span class=\"kw-ttt\">drogue</span> ou <span class=\"kw-ttt\">médicament</span>), d'une <span class=\"kw-etio\">exposition à un toxique</span>, ou de <span class=\"kw-alerte\">causes multiples</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 108 — <span class=\"kw-clinique\">Confusion</span>, démence du sujet âgé</em></p>","frequence":1,"liens":[{"href":"https://www.cen-neurologie.fr/premier-cycle/semiologie-analytique/syndrome-confusionnel","label":"Collège (CEN) — Syndrome confusionnel"}]},{"id":"343-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence du syndrome confusionnel dans la population générale, aux urgences et dans différents milieux hospitaliers","contenu":"<p>Le <span class=\"kw-def\">syndrome confusionnel</span> est <span class=\"kw-clinique\">très fréquent</span>, particulièrement chez la personne âgée de <span class=\"kw-chiffre\">plus de 70 ans</span>. Sa <span class=\"kw-def\">prévalence</span> varie fortement selon le milieu hospitalier considéré.</p>\n      <table >\n        <thead><tr><th>Milieu</th><th>Prévalence</th></tr></thead>\n        <tbody>\n          <tr><td>Services de médecine</td><td><span class=\"kw-chiffre\">15 %</span></td></tr>\n          <tr><td>Gériatrie</td><td><span class=\"kw-chiffre\">30 %</span> — avec un risque de <span class=\"kw-def\">mortalité</span> <span class=\"kw-alerte\">multiplié par 6 à 6 mois</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Chirurgie</span></td><td><span class=\"kw-chiffre\">50 %</span></td></tr>\n          <tr><td>Patients hospitalisés avec TNCM préexistant</td><td><span class=\"kw-chiffre\">&gt; 50 %</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Soins intensifs</span></td><td><span class=\"kw-chiffre\">80 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Pronostic</span> chez le sujet âgé</strong> — le <span class=\"kw-def\">syndrome confusionnel</span> est associé à un <span class=\"kw-alerte\">mauvais pronostic</span>. Après un passage au <span class=\"kw-alerte\">SAU</span> pour <span class=\"kw-clinique\">confusion</span>, on observe une augmentation du risque de :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Décès à 6 mois</span>.</li>\n        <li>Augmentation de la <span class=\"kw-clinique\">durée de séjour</span> hospitalier.</li>\n        <li><span class=\"kw-alerte\">Passage en soins intensifs</span>.</li>\n        <li><span class=\"kw-clinique\">Réadmission précoce</span>.</li>\n        <li><span class=\"kw-clinique\">Institutionnalisation</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 108 — <span class=\"kw-clinique\">Confusion</span>, démence du sujet âgé · 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0},{"id":"343-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","contenu":"<p><strong>Le diagnostic du <span class=\"kw-def\">syndrome confusionnel</span> est exclusivement clinique</strong> — aucun examen ne le confirme. Dogme gériatrique : l'évoquer devant toute <span class=\"kw-alerte\">modification rapide comportementale ou cognitive</span> ou toute <span class=\"kw-alerte\">inversion du rythme nycthéméral</span> chez le patient âgé. La <span class=\"kw-clinique\">rupture avec l'état antérieur</span> se recherche en interrogeant systématiquement un proche.</p>\n      <table >\n        <thead><tr><th>Axe sémiologique</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td>Périodicité</td><td><strong>Installation :</strong> brusque ou rapidement progressive, en <span class=\"kw-chiffre\">minutes, heures ou jours</span> <br><strong>Fluctuation :</strong> <span class=\"kw-clinique\">variation de la sévérité au long de la journée</span> — argument clinique majeur <br><strong>Recrudescence :</strong> troubles surtout présents en période vespérale et dans l'obscurité</td></tr>\n          <tr><td>Attention &amp; conscience</td><td><strong><span class=\"kw-clinique\">Désorientation</span> :</strong> <span class=\"kw-alerte\">désorientation temporo-spatiale constante</span> (tombée en annale) <br><strong>Attention :</strong> difficulté à <span class=\"kw-clinique\">maintenir l'attention</span>, distractibilité, perte du fil du discours <br><strong>Mémoire :</strong> <span class=\"kw-clinique\">trouble de la mémoire à court terme</span> (répéter une phrase longue, mois de l'année à l'envers) et trouble de l'encodage <br><strong>Langage :</strong> <span class=\"kw-alerte\">langage spontané décousu et incohérent</span> (tombé en annale) <br><strong>Pensée :</strong> <span class=\"kw-clinique\">désorganisation de la pensée</span>, altération du raisonnement et du jugement</td></tr>\n          <tr><td>Troubles du comportement</td><td>Perplexité anxieuse <br>Forme agitée : agitation, agressivité <br>Forme ralentie : apathie, somnolence <br><span class=\"kw-clinique\">Délire onirique</span> (plus rarement structuré) et hallucinations, le plus souvent visuelles</td></tr>\n          <tr><td>Autres manifestations</td><td>Labilité de l'humeur et de l'affect (de l'euphorie à la tristesse) <br><span class=\"kw-clinique\">Inversion du cycle veille-sommeil</span> <br>Signes somatiques non spécifiques : <span class=\"kw-clinique\">myoclonies</span>, <span class=\"kw-clinique\">tremblement d'attitude</span> ou d'action, <span class=\"kw-clinique\">astérixis</span> (flapping tremor) <br><span class=\"kw-clinique\">Amnésie lacunaire</span> couvrant toute la durée de l'épisode confusionnel</td></tr>\n          <tr><td><span class=\"kw-imagerie\">EEG</span></td><td><span class=\"kw-bio\">Ralentissement global de l'activité électrique</span> — non spécifique d'une étiologie ; l'<span class=\"kw-imagerie\">EEG</span> n'est pas nécessaire au <span class=\"kw-def\">diagnostic positif</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Critères DSM-5</strong> — le diagnostic répond aux cinq critères A à E : perturbation de l'attention et de l'orientation (A), installation rapide et fluctuante (B), autre perturbation cognitive (C), exclusion d'un <span class=\"kw-def\">trouble neurocognitif préexistant</span> et d'un <span class=\"kw-clinique\">coma</span> (D), <span class=\"kw-alerte\">cause médicale, toxique ou sevrage</span> identifiée (E).</p>\n      <p><strong>Particularités chez l'enfant</strong> — il faut distinguer trois niveaux d'altération de la conscience :</p>\n      <ul>\n        <li><span class=\"kw-def\">Éveil</span> : commandé par la formation réticulée du tronc cérébral, il permet la restauration et le maintien de la vigilance.</li>\n        <li><span class=\"kw-def\">État confusionnel</span> : <span class=\"kw-clinique\">altération aiguë ou subaiguë de la conscience</span>, avec ou sans troubles authentiques de la vigilance.</li>\n        <li><span class=\"kw-def\">Coma</span> : altération aiguë ou subaiguë définie par l'<span class=\"kw-alerte\">absence d'éveil spontané ou provoqué</span>, prolongée au-delà d'<span class=\"kw-chiffre\">1 heure</span> ; il témoigne de lésions anatomiques ou fonctionnelles du tronc cérébral et/ou des hémisphères.</li>\n      </ul>\n      <p>L'évaluation pédiatrique repose sur un <span class=\"kw-clinique\">score de Glasgow adapté à l'âge</span> et la recherche systématique de <span class=\"kw-alerte\">signes de gravité</span> menaçant le <span class=\"kw-alerte\">pronostic vital</span> : <span class=\"kw-alerte\">défaillance</span> hémodynamique, respiratoire ou neurologique, signes d'<span class=\"kw-alerte\">hypertension intracrânienne</span>.</p>\n      <p><strong><span class=\"kw-def\">Score de Glasgow</span> pédiatrique</strong> — adaptations spécifiques sur les réponses verbale et motrice :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Réponse</th><th><span class=\"kw-def\">Score</span></th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"4\"><strong>Ouverture des yeux</strong></td><td><span class=\"kw-clinique\">Spontanée</span></td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>À la demande verbale</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>À la douleur</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>Aucune</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td rowspan=\"5\"><strong>Meilleure réponse verbale</strong></td><td>Orientée, babille, sourit</td><td><span class=\"kw-chiffre\">5</span></td></tr>\n          <tr><td>Pleurs consolables, irritable</td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>Pleurs inconsolables, cris</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>Gémissements</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>Aucune</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td rowspan=\"6\"><strong>Meilleure réponse motrice</strong></td><td>Répond à la demande verbale, gesticulation spontanée</td><td><span class=\"kw-chiffre\">6</span></td></tr>\n          <tr><td>Orientée à la douleur</td><td><span class=\"kw-chiffre\">5</span></td></tr>\n          <tr><td>Évitement non adapté</td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Décortication</span> <em>(flexion à la douleur)</em></td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Décérébration</span> <em>(extension à la douleur)</em></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>Aucune</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Interprétation du Glasgow pédiatrique</strong> — <span class=\"kw-chiffre\">Score maximal 15</span> : état de conscience normal. <span class=\"kw-alerte\">Score ≤ 8</span> : <span class=\"kw-alerte\">coma sévère</span> → prise en charge urgente, libération des voies aériennes et discussion d'une <span class=\"kw-ttt\">intubation</span>. <span class=\"kw-alerte\">Score minimal 3</span> : <span class=\"kw-alerte\">coma</span> profond, mauvais <span class=\"kw-def\">pronostic</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 108 — <span class=\"kw-clinique\">Confusion</span>, démence du sujet âgé · 132 — Troubles cognitifs du sujet âgé · 351 — Agitation et délire aigu</em></p>","frequence":7},{"id":"343-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les trois formes cliniques du syndrome confusionnel","contenu":"<p>Le <span class=\"kw-def\">syndrome confusionnel</span> se décline en <span class=\"kw-chiffre\">trois</span> formes cliniques, définies par la tonalité du trouble du comportement. Les reconnaître évite les erreurs diagnostiques et thérapeutiques.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td>Confuso-onirique (hyperactive)</td><td><span class=\"kw-clinique\">Agitation psychomotrice</span> au premier plan, avec possible opposition aux soins <br><span class=\"kw-clinique\">Délire onirique</span> <br><span class=\"kw-clinique\">Troubles végétatifs</span> : hypersudation, <span class=\"kw-clinique\">tachycardie</span> <br><span class=\"kw-alerte\">Risque iatrogène de surtraiter</span> en vue d'une sédation</td></tr>\n          <tr><td>Stuporeuse (hypoactive)</td><td><strong>Forme la plus fréquente et de plus mauvais <span class=\"kw-def\">pronostic</span></strong> <br><span class=\"kw-clinique\">Apathie</span>, repli sur soi <br><span class=\"kw-clinique\">Ralentissement psychomoteur</span>, somnolence <br><span class=\"kw-alerte\">Sous-diagnostiquée</span> : confondue avec une <span class=\"kw-def\">dépression</span> ou un trouble neurocognitif majeur</td></tr>\n          <tr><td>Mixte</td><td><span class=\"kw-clinique\">Alternance irrégulière et imprévisible</span> des états des deux formes précédentes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique EDN</strong> — la forme <span class=\"kw-alerte\">hypoactive</span> est paradoxalement la <strong>plus fréquente</strong> et la <strong>plus mal pronostiquée</strong>, tout en étant la plus <span class=\"kw-alerte\">sous-diagnostiquée</span> : un patient âgé apathique et somnolent n'est pas « calme », il peut être confus.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 351 — Agitation et délire aigu</em></p>","frequence":2},{"id":"343-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le principal outil de dépistage clinique","contenu":"<p>Le principal outil de <span class=\"kw-def\">dépistage</span> clinique est la <span class=\"kw-def\">CAM</span> (<span class=\"kw-def\">Confusion Assessment Method</span>). C'est un outil d'aide au diagnostic <span class=\"kw-clinique\">rapide</span> (réalisation en <span class=\"kw-chiffre\">5 à 10 minutes</span>) et reproductible, aux performances élevées : <span class=\"kw-bio\">sensibilité 85 %</span>, <span class=\"kw-bio\">spécificité 93 %</span>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>1 — Début aigu &amp; fluctuation <span class=\"kw-alerte\">(obligatoire)</span></td><td>Changement aigu de l'état mental de base ; <span class=\"kw-clinique\">fluctuation</span> du comportement au cours de la journée</td></tr>\n          <tr><td>2 — Inattention <span class=\"kw-alerte\">(obligatoire)</span></td><td>Difficulté à <span class=\"kw-clinique\">focaliser l'attention</span> ; perte du fil du discours ; distractibilité</td></tr>\n          <tr><td>3 — Désorganisation de la pensée</td><td>Discours <span class=\"kw-clinique\">incohérent et désorganisé</span> ; suite d'idées illogique ; coq-à-l'âne</td></tr>\n          <tr><td>4 — Altération de la vigilance</td><td>État autre que « alerte » : <span class=\"kw-clinique\">léthargique</span>, stuporeux ou comateux</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Algorithme</strong> — la CAM est <span class=\"kw-alerte\">positive si : 1 + 2 + (3 et/ou 4)</span>. Les critères 1 et 2 doivent <strong>toujours</strong> être présents, en association avec le critère 3 et/ou le critère 4.</p>\n      <div class=\"callout callout-warn\"><strong>Source lacunaire</strong> — la variante <span class=\"kw-def\">CAM-ICU</span>, adaptée au patient de <span class=\"kw-alerte\">soins intensifs</span> non verbal (intubé, ventilé), n'est pas détaillée dans les fiches sources de l'item 343. À compléter manuellement à partir d'une référence dédiée.</div>","frequence":0,"liens":[{"href":"https://guide.hpci.ch/depistage-de-letat-confusionnel-aigu-outil-cam-confusion-assessment-method/","label":"Guide HPCI — CAM (outil de dépistage)"}]},{"id":"343-6","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les situations nécessitant une prise en charge en urgence","contenu":"<p>Le <span class=\"kw-def\">syndrome confusionnel</span> est une <span class=\"kw-alerte\">urgence diagnostique ET thérapeutique</span> : la cause est souvent une pathologie grave, voire rapidement létale, et la <span class=\"kw-clinique\">confusion</span> elle-même est dangereuse. Il impose presque toujours une <span class=\"kw-alerte\">hospitalisation immédiate</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale</strong> — deux dangers se cumulent : la <span class=\"kw-alerte\">cause</span> (<span class=\"kw-def\">diabète</span> décompensé, <span class=\"kw-def\">insuffisance rénale aiguë</span>, hémorragie méningée…) et la <span class=\"kw-alerte\">confusion elle-même</span> (troubles majeurs du comportement, <span class=\"kw-clinique\">déshydratation</span>, chutes).</div>\n      <p><strong>Situations imposant une prise en charge en <span class=\"kw-alerte\">urgence</span></strong> :</p>\n      <table >\n        <thead><tr><th>Drapeau</th><th>Conduite urgente</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Signe de localisation neurologique</span></td><td><span class=\"kw-imagerie\">TDM cérébrale urgente</span> — suspicion d'<span class=\"kw-etio\">AVC</span>, hémorragie méningée, hématome, processus expansif</td></tr>\n          <tr><td><span class=\"kw-etio\">Traumatisme crânien</span>, même mineur, ou chute peu claire</td><td><span class=\"kw-imagerie\">TDM cérébrale urgente</span> — recherche d'un hématome intracrânien</td></tr>\n          <tr><td><span class=\"kw-etio\">Fièvre sans point d'appel</span> ou <span class=\"kw-def\">syndrome méningé</span></td><td><span class=\"kw-imagerie\">Ponction lombaire</span> en <span class=\"kw-alerte\">urgence</span> — réalisée après <span class=\"kw-imagerie\">TDM</span> si signe de localisation</td></tr>\n          <tr><td>Suspicion de <span class=\"kw-etio\">confusion post-critique</span> d'<span class=\"kw-def\">épilepsie</span></td><td><span class=\"kw-imagerie\">EEG</span> — recherche d'un <span class=\"kw-alerte\">état de mal</span> non convulsivant</td></tr>\n          <tr><td><span class=\"kw-etio\">Sevrage alcoolique sévère</span> (delirium tremens)</td><td><span class=\"kw-alerte\">Urgence</span> vitale — prise en charge spécialisée immédiate</td></tr>\n          <tr><td><span class=\"kw-etio\">Hypoglycémie</span>, <span class=\"kw-clinique\">hyperthermie</span>, hypothermie</td><td>Correction urgente du trouble identifié</td></tr>\n          <tr><td><span class=\"kw-etio\">Intoxication aiguë</span></td><td>Décontamination, antidote spécifique selon le <span class=\"kw-etio\">toxique</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée · 151 — <span class=\"kw-def\">Méningite</span> - méningoencéphalite · 105 — Epilepsie · 240 — Hypoglycémie · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 337 — Intoxication aiguë</em></p>","frequence":1},{"id":"343-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","contenu":"<p><strong>Objectif majeur</strong> — les étiologies du <span class=\"kw-def\">syndrome confusionnel</span> sont innombrables. Deux principes structurent l'enquête : distinguer les causes <span class=\"kw-def\">neurologiques</span> des causes <span class=\"kw-def\">non neurologiques</span> (chez le sujet âgé, les causes non neurologiques sont de loin les plus fréquentes) ; et toujours rechercher des causes <span class=\"kw-alerte\">multiples et intriquées</span>.</p>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span></strong> (<span class=\"kw-def\">terrain</span> prédisposant) :</p>\n      <table >\n        <thead><tr><th>Terrain</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr><td>Facteurs prédisposants</td><td><span class=\"kw-clinique\">Âge ≥ 80 ans</span> ; ATCD de confusion, notamment postopératoire ; trouble neurocognitif ou troubles cognitifs sous-jacents ; immobilisation, aggravée par la contention physique ; déficit sensoriel visuel ou auditif ; <span class=\"kw-def\">comorbidités</span> multiples ; <span class=\"kw-clinique\">dénutrition</span> ; <span class=\"kw-clinique\">polymédication</span> ; troubles de l'humeur</td></tr>\n          <tr><td>Sujet âgé — causes simples à traquer</td><td>Privilégier les <span class=\"kw-etio\">causes non neurologiques</span> facilement réversibles : <span class=\"kw-clinique\">fécalome</span> ; <span class=\"kw-clinique\">globe vésical</span> (rétention aiguë d'urine) ; douleur ; troubles neurosensoriels</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Étiologies — cinq grandes catégories</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Toxiques</td><td><strong><span class=\"kw-etio\">Alcool</span> :</strong> ivresse aiguë ; <span class=\"kw-ttt\">sevrage</span> <br><strong>Drogues :</strong> <span class=\"kw-etio\">héroïne</span> ; <span class=\"kw-etio\">cocaïne</span> <br><strong>Toxiques industriels :</strong> <span class=\"kw-etio\">pesticides</span> ; solvants ; intoxication au <span class=\"kw-etio\">CO</span> <br><strong>Médicaments :</strong> <span class=\"kw-ttt\">psychotropes</span> (BZD ; antidépresseurs ; neuroleptiques ; <span class=\"kw-ttt\">lithium</span> ; antiépileptiques ; <span class=\"kw-ttt\">opioïdes</span>) ; <span class=\"kw-ttt\">anti-parkinsoniens</span> ; <span class=\"kw-ci\">anticholinergiques</span> <br><strong>Pièges :</strong> le <span class=\"kw-alerte\">sevrage brutal d'un psychotrope</span> est lui-même confusiogène ; chez le sujet âgé, l'insuffisant hépatique ou rénal, presque tous les médicaments sont incriminables</td></tr>\n          <tr><td>Métaboliques</td><td><strong>Hydro-électrolytiques :</strong> <span class=\"kw-bio\">hyper/hyponatrémie</span> ; <span class=\"kw-bio\">hypokaliémie</span> ; <span class=\"kw-bio\">hypercalcémie</span> ; déshydratation <br><strong><span class=\"kw-bio\">Glycémie</span> :</strong> <span class=\"kw-bio\">hypoglycémie</span> <br><strong>Endocrinopathies :</strong> <span class=\"kw-alerte\">décompensation</span> d'un <span class=\"kw-def\">diabète</span> ; <span class=\"kw-etio\">insuffisance surrénale aiguë</span> ; <span class=\"kw-etio\">hypothyroïdie</span> ; insuffisance antéhypophysaire aiguë <br><strong>Insuffisances d'organe :</strong> rénale ; hépatique ; cardio-respiratoire, décompensées ou aiguës <br><strong>Carences vitaminiques :</strong> <span class=\"kw-bio\">B1</span> (<span class=\"kw-etio\">Gayet-Wernicke</span>, <span class=\"kw-etio\">Korsakoff</span>) ; <span class=\"kw-clinique\">B3</span> (<span class=\"kw-etio\">pellagre</span>) ; <span class=\"kw-etio\">Marchiafava-Bignami</span> ; <span class=\"kw-bio\">B9</span> / <span class=\"kw-bio\">B12</span></td></tr>\n          <tr><td>Neurologiques</td><td><span class=\"kw-etio\">Hémorragie méningée</span> <br><span class=\"kw-etio\">Méningites et méningo-encéphalites</span> : bactériennes ; virales ; parasitaires ; à prions <br><span class=\"kw-etio\">Processus expansifs intracrâniens</span> : tumeurs ; <span class=\"kw-clinique\">abcès</span> ; hématomes <br><span class=\"kw-etio\">Traumatisme crânien</span> : <span class=\"kw-etio\">hématome sous-dural</span> ; <span class=\"kw-etio\">extra-dural</span> ; <span class=\"kw-etio\">intraparenchymateux</span> <br><span class=\"kw-etio\">Infarctus cérébraux</span> : tronc cérébral ; ganglions de la base ; <span class=\"kw-clinique\">infarctus</span> de grande taille <br><span class=\"kw-etio\">Épilepsie généralisée</span> : phase post-critique ou <span class=\"kw-alerte\">état de mal</span> <br>Toute pathologie neurologique chronique décompensée par un stress physique</td></tr>\n          <tr><td>Infectieuses &amp; <span class=\"kw-clinique\">fièvre</span></td><td><span class=\"kw-etio\">Infections urinaires</span> ; <span class=\"kw-etio\">infections pulmonaires</span> <br>Toute <span class=\"kw-clinique\">fièvre</span> peut être confusiogène, d'autant plus s'il existe une détérioration cognitive préalable</td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-etio\">Hypothermie</span> <br><span class=\"kw-etio\">Hypoxie / anoxie cérébrale</span> : <span class=\"kw-alerte\">arrêt cardiaque</span>, <span class=\"kw-alerte\">état de choc</span> <br>Post-opératoire <br><span class=\"kw-alerte\">Causes intriquées</span> : alcool + médicaments ; polymédication ; alcool + traumatisme crânien</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Particularités chez l'enfant</strong> — les causes se répartissent ainsi <em>(complément hors fiche source 343 directe — issu du référentiel pédiatrique général, à recouper avec le Collège)</em> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies pédiatriques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Défaillance</span> vitale</td><td><span class=\"kw-etio\">Insuffisance respiratoire aiguë</span> hypercapnique ou hypoxique ; <span class=\"kw-etio\">état de choc</span> ; <span class=\"kw-etio\">crise hypertensive maligne</span></td></tr>\n          <tr><td>Désordres métaboliques</td><td><span class=\"kw-etio\">Hypoglycémie</span> ; <span class=\"kw-bio\">dysnatrémie</span> ; <span class=\"kw-bio\">acidocétose</span></td></tr>\n          <tr><td>Intoxications</td><td>Deux pics de fréquence : <span class=\"kw-chiffre\">enfant &lt; 5 ans</span> et <span class=\"kw-chiffre\">adolescent</span> ; toxiques fréquents : <span class=\"kw-etio\">CO</span>, <span class=\"kw-etio\">paracétamol</span></td></tr>\n          <tr><td>Causes neurologiques</td><td><span class=\"kw-etio\">Traumatisme crânien</span> — <span class=\"kw-alerte\">toujours évoquer le TC infligé</span> (secouement) chez le nourrisson ; <span class=\"kw-etio\">infections neuroméningées</span> ; <span class=\"kw-etio\">état de mal épileptique</span> ; <span class=\"kw-etio\">tumeurs cérébrales</span> ; <span class=\"kw-etio\">AVC</span></td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-etio\">Anomalies héréditaires du métabolisme</span> ; <span class=\"kw-etio\">pathologie de système</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pédiatrie</strong> — chez le nourrisson présentant peu de lésions externes, le <span class=\"kw-alerte\">traumatisme crânien infligé</span> (syndrome du bébé secoué) doit être systématiquement évoqué. À l'inverse, les crises fébriles simples ne provoquent pas de trouble de conscience prolongé.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 105 — Epilepsie · 132 — Troubles cognitifs du sujet âgé · 151 — <span class=\"kw-def\">Méningite</span> - méningoencéphalite · 240 — Hypoglycémie · 268 — Hypercalcémie · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë - <span class=\"kw-clinique\">déshydratation</span> · 325 — Risque <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-etio\">iatrogène</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 337 — Intoxication aiguë · 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée</em></p>","frequence":8},{"id":"343-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> de <span class=\"kw-chiffre\">première intention</span> devant un <span class=\"kw-def\">syndrome confusionnel</span> est systématique lorsqu'aucune cause évidente n'a été identifiée à l'examen : chaque examen vise une étiologie précise.</p>\n      <p><strong>Bilan minimum</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">SaO2</span> ; <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">créatininémie</span> ; <span class=\"kw-bio\">ionogramme sanguin</span> ; <span class=\"kw-bio\">calcémie</span> ; <span class=\"kw-bio\">glycémie</span> ; <span class=\"kw-bio\">protides totaux</span> ; <span class=\"kw-bio\">bandelette urinaire</span> ; <span class=\"kw-clinique\">ECG</span>.</li>\n        <li>Le CEN (neurologie) ajoute : <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">bilan d'hémostase</span> (<span class=\"kw-bio\">TP</span>-<span class=\"kw-bio\">TCA</span>) ; <span class=\"kw-imagerie\">radiographie thoracique</span>.</li>\n      </ul>\n      <p><strong>Rationnel</strong> — chaque ligne du bilan cible une étiologie identifiée :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Étiologie recherchée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span></td><td>Cause <span class=\"kw-etio\">infectieuse</span> ou <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Ionogramme</span> sanguin</td><td><span class=\"kw-etio\">Trouble hydro-électrolytique</span> : dysnatrémie, hypokaliémie</td></tr>\n          <tr><td><span class=\"kw-bio\">Calcémie</span></td><td><span class=\"kw-etio\">Hyper- ou hypocalcémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Glycémie</span></td><td><span class=\"kw-etio\">Hypoglycémie</span> ou <span class=\"kw-alerte\">décompensation</span> diabétique</td></tr>\n          <tr><td>Protides totaux</td><td><span class=\"kw-etio\">Dénutrition</span>, déshydratation</td></tr>\n          <tr><td>Bandelette urinaire</td><td><span class=\"kw-etio\">Infection urinaire</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">ECG</span></td><td>Ischémie myocardique, trouble du rythme</td></tr>\n          <tr><td>Bilan hépatique</td><td><span class=\"kw-etio\">Encéphalopathie hépatique</span></td></tr>\n          <tr><td>Bilan d'hémostase</td><td>Suspicion d'<span class=\"kw-etio\">hématome intracrânien</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 240 — Hypoglycémie · 268 — Hypercalcémie</em></p>","frequence":2},{"id":"343-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant un état confusionnel et/ou un trouble de la conscience chez l’enfant et chez l’adulte","contenu":"<p>L'imagerie cérébrale <span class=\"kw-alerte\">n'est pas systématique</span> devant un <span class=\"kw-def\">syndrome confusionnel</span> : elle est demandée <span class=\"kw-clinique\">en urgence au moindre doute</span> de <span class=\"kw-clinique\">lésion</span> neurologique sous-jacente, ou en seconde intention si le bilan initial reste négatif.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">TDM cérébrale</span></td><td><strong>1ʳᵉ intention :</strong> <span class=\"kw-alerte\">signe de localisation</span> ; suspicion d'hémorragie méningée ; <span class=\"kw-alerte\">traumatisme crânien</span> même mineur ; chute dans des circonstances peu claires ; traitement <span class=\"kw-alerte\">anticoagulant</span> ; <span class=\"kw-clinique\">confusion</span> d'installation brutale <br><strong>2ⁿᵈᵉ intention :</strong> bilan de 1ʳᵉ intention négatif avec persistance de la <span class=\"kw-clinique\">confusion</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Ponction lombaire</span></td><td><strong>1ʳᵉ intention :</strong> <span class=\"kw-alerte\">fièvre sans autre point d'appel</span> <span class=\"kw-etio\">infectieux</span> ; <span class=\"kw-def\">syndrome méningé</span> ; suspicion d'hémorragie méningée <br><strong>2ⁿᵈᵉ intention :</strong> bilan négatif avec <span class=\"kw-clinique\">confusion</span> persistante</td></tr>\n          <tr><td><span class=\"kw-imagerie\">EEG</span></td><td>Suspicion de <span class=\"kw-etio\">confusion post-critique</span> d'<span class=\"kw-def\">épilepsie</span> ; bilan étiologique négatif (<span class=\"kw-def\">dépistage</span> des <span class=\"kw-etio\">épilepsies infracliniques</span> et de l'<span class=\"kw-alerte\">état de mal</span> non convulsivant)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">IRM cérébrale</span></td><td>Non systématique ; discutée en 2ⁿᵈᵉ intention : <span class=\"kw-etio\">encéphalite herpétique</span> ; lésions inflammatoires (<span class=\"kw-etio\">SEP</span>) ; lésions ischémiques fines</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège — séquence <span class=\"kw-imagerie\">TDM</span> puis PL</strong> — devant une <span class=\"kw-clinique\">confusion</span> fébrile avec <span class=\"kw-alerte\">signe de localisation</span>, la <span class=\"kw-imagerie\">ponction lombaire</span> ne se réalise qu'<strong>après la <span class=\"kw-imagerie\">TDM</span> cérébrale</strong>, afin d'éliminer une <span class=\"kw-alerte\">hypertension intracrânienne</span> avant la <span class=\"kw-ttt\">ponction</span>.</div>\n      <p><strong>Particularités chez l'enfant</strong> — devant un trouble de conscience pédiatrique, l'imagerie est <span class=\"kw-imagerie\">large et urgente</span> : <span class=\"kw-imagerie\">TDM cérébrale</span> en cas de contexte traumatique évident, avec protection du rachis cervical. En cas de suspicion de <span class=\"kw-alerte\">syndrome du bébé secoué</span>, le bilan associe <span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-clinique\">fond d'œil</span> (recherche d'<span class=\"kw-radio\">hémorragies rétiniennes</span>), <span class=\"kw-imagerie\">IRM cérébrale</span> et radiographies. La mesure de la <span class=\"kw-clinique\">pression intracrânienne</span> oriente vers la neurochirurgie.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée · 151 — <span class=\"kw-def\">Méningite</span> - méningoencéphalite</em></p>","frequence":2},{"id":"343-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","contenu":"<p>La prise en charge d'un <span class=\"kw-def\">syndrome confusionnel</span> est une <span class=\"kw-alerte\">urgence médicale, diagnostique et thérapeutique</span>, nécessitant presque toujours une <span class=\"kw-alerte\">hospitalisation immédiate</span>. Elle repose sur une démarche en deux temps.</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>1 — Retentissement vital</td><td>Évaluer le retentissement à court terme (constantes vitales) et <span class=\"kw-alerte\">traiter immédiatement les troubles vitaux</span> : <span class=\"kw-alerte\">état de choc</span>, <span class=\"kw-clinique\">hypothermie</span>…</td></tr>\n          <tr><td>2 — Traitement étiologique</td><td><span class=\"kw-alerte\">Priorité absolue</span> — seul le traitement de la cause permet la guérison. En gériatrie : correction des <span class=\"kw-def\">facteurs précipitants</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mesures générales non médicamenteuses</strong> — à privilégier systématiquement :</p>\n      <ul>\n        <li>Retirer les <span class=\"kw-ttt\">traitements non indispensables</span> ou redondants, surtout les <span class=\"kw-ttt\">psychotropes</span> — <span class=\"kw-ci\">mais pas de sevrage brutal d'un psychotrope ancien</span> (le <span class=\"kw-ttt\">sevrage</span> est lui-même confusiogène) ; diminuer la posologie des <span class=\"kw-ttt\">corticoïdes</span>.</li>\n        <li>Maintenir hydratation et nutrition, au besoin par voie parentérale ; favoriser l'élimination (accès aux toilettes, laxatifs).</li>\n        <li>Environnement calme : chambre individuelle, lumière tamisée, porte ouverte pour la <span class=\"kw-def\">surveillance</span> ; limiter les visites aux référents.</li>\n        <li>Lutter contre l'isolement sensoriel : prothèses auditives, lunettes ; maintenir la mobilité ; restaurer les repères spatio-temporels (calendrier, horloge).</li>\n        <li><span class=\"kw-def\">Surveillance</span> fréquente et régulière des constantes vitales et de la conscience ; évaluer et traiter la <span class=\"kw-clinique\">douleur</span>.</li>\n      </ul>\n      <p><strong>Traitements symptomatiques</strong> — recours rare, en dernier recours, voie orale privilégiée :</p>\n      <table >\n        <thead><tr><th>Indication</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Anxiété <strong>majeure</strong></td><td><span class=\"kw-ttt\">BZD à demi-vie courte</span> à faible dose PO : <span class=\"kw-ttt\">oxazépam</span> ou <span class=\"kw-ttt\">alprazolam</span> <br>Pas de traitement si l'anxiété n'est pas majeure <br><span class=\"kw-ci\">Éviter hydroxyzine, cyamémazine, halopéridol</span> (composante anticholinergique)</td></tr>\n          <tr><td>Délire / hallucinations avec agitation compromettant la sécurité</td><td><span class=\"kw-ttt\">Neuroleptique atypique</span> à faible dose PO : <span class=\"kw-ttt\">rispéridone</span> ou <span class=\"kw-ttt\">olanzapine</span> orodispersible <br><span class=\"kw-ci\">Éviter les formes injectables</span> ; <span class=\"kw-ttt\">tiapride IM</span> en dernier recours <br>Tout délire ne justifie pas un traitement <span class=\"kw-etio\">médicamenteux</span></td></tr>\n          <tr><td>Maladie à corps de Lewy ou maladie de Parkinson</td><td><span class=\"kw-ci\">Neuroleptiques classiques contre-indiqués</span> — utiliser la <span class=\"kw-ttt\">clozapine</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Contention physique</strong> — à envisager en dernier lieu, après échec de toutes les autres mesures : sur prescription médicale engageant la responsabilité du prescripteur, sur une durée limitée, réévaluée pluriquotidiennement. La <span class=\"kw-ci\">contention physique</span> est elle-même une source d'aggravation du <span class=\"kw-def\">syndrome confusionnel</span>.</p>\n      <p><strong>Particularités chez l'enfant</strong> <em>(complément hors fiche source 343 directe — issu du référentiel pédiatrique général, à recouper avec le Collège)</em> — la prise en charge est hospitalière et hiérarchisée : recherche de <span class=\"kw-alerte\">signes de gravité</span> menaçant le <span class=\"kw-alerte\">pronostic vital</span>, séquence <span class=\"kw-def\">« ABCDE »</span> (Airways, Breathing, Circulation, Disability, Exposure), libération des voies aériennes, <span class=\"kw-ttt\">oxygénothérapie</span> ± ventilation mécanique si <span class=\"kw-chiffre\">Glasgow &lt; 8</span>, objectifs de FC et de PA adaptés à l'âge, <span class=\"kw-bio\">glycémie capillaire</span> et <span class=\"kw-bio\">bandelette urinaire</span>, prévention de l'<span class=\"kw-alerte\">HTIC</span> (décubitus dorsal à 30°, normoxie et normocapnie).</p>\n      <div class=\"callout callout-warn\"><strong>Trois pièges thérapeutiques</strong> — éviter les <span class=\"kw-ci\">anticholinergiques</span> chez le confus âgé ; ne <span class=\"kw-ci\">jamais sevrer brutalement</span> un psychotrope ancien (<span class=\"kw-ttt\">sevrage</span> confusiogène) ; réserver la <span class=\"kw-ci\">contention physique</span> au tout dernier recours, car elle aggrave l'agitation. Enfin, ne pas conclure trop vite à un échec : la régression du <span class=\"kw-def\">syndrome confusionnel</span> peut être lente, même après résolution de la cause.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 108 — <span class=\"kw-clinique\">Confusion</span>, démence du sujet âgé · 325 — Risque <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-etio\">iatrogène</span> · 351 — Agitation et délire aigu</em></p>","frequence":3}],"astuces":[{"type":"danger","titre":"Vitamine B1 AVANT tout glucose chez l'alcoolique","contenu":"Chez tout patient alcoolique chronique, dénutri ou avec suspicion de Gayet-Wernicke, perfuser systématiquement de la thiamine (B1) 500 mg IV AVANT d'apporter du glucose. Le glucose seul précipite l'encéphalopathie de Gayet-Wernicke (confusion + ophtalmoplégie + ataxie) qui peut laisser des séquelles définitives (syndrome de Korsakoff)."},{"type":"warn","titre":"Forme hypoactive = piège diagnostique majeur","contenu":"50 % des confusions sont hypoactives (apathie, somnolence, repli) : confondues avec dépression ou démence, sous-diagnostiquées → cause non traitée, mortalité plus élevée. Utiliser le CAM systématiquement chez tout sujet âgé hospitalisé, même calme."},{"type":"tip","titre":"Le réflexe « 5G » devant une confusion aiguë","contenu":"Glycémie capillaire (hypoglycémie), Glasgow + signes focaux (AVC), Gaz du sang (hypoxie/hypercapnie/HbCO), Gestes vitaux (O2, VVP), Globe vésical/fécalome (palpation, écho vésicale). Ces 5 réflexes sauvent des vies en quelques minutes."},{"type":"danger","titre":"Démence à corps de Lewy : neuroleptiques interdits","contenu":"Devant une confusion + hallucinations visuelles + parkinsonisme + fluctuation cognitive, penser démence à corps de Lewy. Les neuroleptiques (même atypiques) provoquent une aggravation parkinsonienne sévère, voire un syndrome malin. Préférer la quétiapine ou la clozapine à doses très faibles."},{"type":"info","titre":"Confusion chez le sujet âgé = iatrogénie jusqu'à preuve du contraire","contenu":"Réviser systématiquement l'ordonnance : anticholinergiques (atropiniques, antihistaminiques H1, ADP tricycliques, neuroleptiques classiques, oxybutynine, etc.), benzodiazépines, opioïdes, corticoïdes, anti-parkinsoniens. Outils : échelle de Beers, START/STOPP, échelle anticholinergique de Boustani."},{"type":"warn","titre":"Infection urinaire = cause n°1 chez le sujet âgé confus","contenu":"Devant toute confusion aiguë chez un sujet âgé, BU + ECBU systématique. Une cystite peut être révélée par une simple confusion, sans aucune autre symptôme urinaire ni fièvre. Antibiothérapie adaptée à l'antibiogramme."}],"strategie":{"urgence":"<p><strong>Degré :</strong> le <span class=\"kw-def\">syndrome confusionnel</span> est une <span class=\"kw-alerte\">urgence diagnostique ET thérapeutique</span> qui impose presque toujours une <span class=\"kw-alerte\">hospitalisation</span> — double danger : la <span class=\"kw-def\">cause</span> (souvent grave) ET la <span class=\"kw-clinique\">confusion</span> elle-même.</p><p><strong><span class=\"kw-alerte\">Détresse</span> vitale <span class=\"q\">— priorité absolue</span></strong></p><p>traiter immédiatement le trouble vital avant toute enquête étiologique</p><ul><li><span class=\"kw-alerte\">État de choc</span>, <span class=\"kw-alerte\">hypoxie</span>, <span class=\"kw-alerte\">hypoglycémie</span>, <span class=\"kw-alerte\">hyperthermie</span> ou <span class=\"kw-alerte\">hypothermie</span></li></ul><p><strong>Signe de localisation · <span class=\"kw-etio\">TC</span> même mineur · chute peu claire · <span class=\"kw-ttt\">anticoagulant</span></strong></p><p><span class=\"kw-imagerie\">TDM cérébrale</span> sans délai</p><ul><li>Suspicion d'<span class=\"kw-etio\">hématome intracrânien</span>, d'<span class=\"kw-etio\">AVC</span> ou d'<span class=\"kw-etio\">hémorragie méningée</span></li></ul><p><strong>Confusion <span class=\"kw-clinique\">fébrile</span> · <span class=\"kw-alerte\">syndrome méningé</span></strong></p><p><span class=\"kw-imagerie\">ponction lombaire</span> en <span class=\"kw-alerte\">urgence</span> (après <span class=\"kw-imagerie\">TDM</span> si signe de localisation)</p><ul><li>Suspicion de <span class=\"kw-etio\">méningite</span> / <span class=\"kw-etio\">méningo-encéphalite</span></li></ul><p><strong>Suspicion de <span class=\"kw-etio\">confusion post-critique</span> d'épilepsie</strong></p><p><span class=\"kw-bio\">EEG</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li>Recherche d'un <span class=\"kw-alerte\">état de mal non convulsivant</span></li></ul><p><strong><span class=\"kw-alerte\">Sevrage alcoolique sévère</span> <span class=\"q\">— delirium tremens</span></strong></p><p>prise en charge spécialisée immédiate + <span class=\"kw-ttt\">vitamine B1</span></p><ul><li><span class=\"kw-alerte\">Urgence</span> vitale spécifique</li></ul>","hospit":"<p><strong>Règle :</strong> le <span class=\"kw-def\">syndrome confusionnel</span> est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span> impliquant presque toujours une <span class=\"kw-alerte\">hospitalisation</span>.<br><strong>Orientation (sujet âgé) :</strong> anticiper le parcours de soins vers une <span class=\"kw-def\">structure gériatrique</span> ou une <span class=\"kw-def\">expertise gériatrique</span>, avec <span class=\"kw-def\">surveillance</span> et suivi.<br><strong>À distance :</strong> réévaluer l'état cognitif à <span class=\"kw-chiffre\">6 mois</span> — la confusion peut révéler un <span class=\"kw-def\">syndrome démentiel</span> débutant.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Signe de localisation neurologique</span> → suspicion d'<span class=\"kw-etio\">AVC</span>, d'<span class=\"kw-etio\">hémorragie méningée</span> ou d'<span class=\"kw-etio\">hématome</span></li><li><span class=\"kw-etio\">Traumatisme crânien</span> même mineur, ou <span class=\"kw-alerte\">chute dans des circonstances peu claires</span></li><li><span class=\"kw-clinique\">Fièvre</span> sans point d'appel ou <span class=\"kw-alerte\">syndrome méningé</span></li><li><span class=\"kw-alerte\">Trouble de la vigilance</span> / <span class=\"kw-alerte\">Glasgow ≤ 8</span> (<span class=\"kw-alerte\">coma</span> sévère, enfant comme adulte)</li><li><span class=\"kw-alerte\">Décortication</span> ou <span class=\"kw-alerte\">décérébration</span> (réponse motrice pathologique)</li><li><span class=\"kw-alerte\">Sevrage alcoolique sévère</span> (delirium tremens)</li><li><span class=\"kw-alerte\">Hypoglycémie</span>, <span class=\"kw-alerte\">hyperthermie</span> ou <span class=\"kw-alerte\">hypothermie</span></li><li>Enfant : <span class=\"kw-alerte\">défaillance hémodynamique, respiratoire ou neurologique</span>, signes d'<span class=\"kw-alerte\">hypertension intracrânienne</span></li></ul>","principes":"<p><strong>Règle d'or :</strong> le <span class=\"kw-ttt\">traitement étiologique</span> est la <span class=\"kw-alerte\">priorité absolue</span> — seul le traitement de la cause permet la guérison ; le traitement <span class=\"kw-etio\">médicamenteux</span> symptomatique reste <span class=\"kw-alerte\">rare et de dernier recours</span>.</p><p><strong>Démarche en 2 temps</strong></p><ul><li><span class=\"kw-alerte\">Retentissement vital</span> d'abord : constantes, traiter les troubles vitaux immédiats (ex. <span class=\"kw-alerte\">choc</span>)</li><li><span class=\"kw-ttt\">Traitement étiologique</span> ensuite — gériatrie : correction des <span class=\"kw-etio\">facteurs précipitants</span></li></ul><p><strong>Mesures non médicamenteuses <span class=\"q\">— à privilégier</span></strong></p><ul><li>Retirer les <span class=\"kw-ttt\">traitements non indispensables</span> (surtout <span class=\"kw-ttt\">psychotropes</span>) — <span class=\"kw-ci\">jamais de sevrage brutal d'un psychotrope ancien</span> ; diminuer les <span class=\"kw-ttt\">corticoïdes</span></li><li>Maintenir <span class=\"kw-clinique\">hydratation</span> et <span class=\"kw-clinique\">nutrition</span> (au besoin parentérale) ; favoriser l'élimination (<span class=\"kw-clinique\">fécalome</span>, <span class=\"kw-clinique\">globe vésical</span>)</li><li>Environnement calme, chambre individuelle, repères spatio-temporels (calendrier, horloge) ; lutter contre l'isolement sensoriel (prothèses auditives, lunettes)</li><li>Limiter les dispositifs invasifs : cathéter, sonde urinaire, perfusion</li></ul><p><strong>Traitement symptomatique <span class=\"q\">— rare, voie orale privilégiée</span></strong></p><ul><li><span class=\"kw-clinique\">Anxiété majeure</span> : <span class=\"kw-ttt\">BZD à demi-vie courte</span> (<span class=\"kw-ttt\">oxazépam</span>, <span class=\"kw-ttt\">alprazolam</span>) — <span class=\"kw-ci\">éviter hydroxyzine, cyamémazine, halopéridol</span> (anticholinergiques)</li><li><span class=\"kw-clinique\">Délire / hallucinations</span> avec agitation dangereuse : <span class=\"kw-ttt\">neuroleptique atypique</span> (<span class=\"kw-ttt\">rispéridone</span>, <span class=\"kw-ttt\">olanzapine</span>) — <span class=\"kw-ci\">éviter les formes injectables</span>, <span class=\"kw-ttt\">tiapride IM</span> en dernier recours</li><li><span class=\"kw-etio\">Maladie à corps de Lewy</span> / <span class=\"kw-etio\">maladie de Parkinson</span> : <span class=\"kw-ci\">neuroleptiques classiques contre-indiqués</span> → <span class=\"kw-ttt\">clozapine</span></li></ul><p><strong>Contention physique <span class=\"q\">— dernier recours</span></strong></p><ul><li><span class=\"kw-ci\">À éviter autant que possible</span> : elle aggrave agitation et angoisse</li><li>Si indispensable : prescription médicale (responsabilité du prescripteur), durée limitée, <span class=\"kw-def\">réévaluation</span> pluriquotidienne</li></ul><p><strong>Enfant <span class=\"q\">— séquence <span class=\"kw-clinique\">ABCDE</span></span></strong></p><ul><li><span class=\"kw-ttt\">Airway-Breathing-Circulation-Disability-Exposure</span> : libération des VAS, <span class=\"kw-ttt\">oxygénothérapie</span> ± <span class=\"kw-ttt\">ventilation mécanique</span> si <span class=\"kw-chiffre\">Glasgow &lt; 8</span></li><li><span class=\"kw-bio\">Glycémie capillaire</span>, <span class=\"kw-bio\">bandelette urinaire</span> ; prévention de l'<span class=\"kw-alerte\">HTIC</span> (décubitus dorsal à 30°, normoxie/normocapnie)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> :</strong> répétée et rapprochée des <span class=\"kw-clinique\">constantes vitales</span> et de l'état de <span class=\"kw-clinique\">conscience</span> ; rechercher systématiquement une <span class=\"kw-clinique\">douleur</span> non soulagée, un <span class=\"kw-clinique\">fécalome</span>, une <span class=\"kw-clinique\">rétention aiguë d'urine</span>.<br><strong><span class=\"kw-clinique\">Évolution</span> :</strong> la <span class=\"kw-clinique\">confusion</span> peut régresser <span class=\"kw-alerte\">lentement</span>, même après résolution de la cause — être patient avant de conclure à un échec.<br><strong>À distance :</strong> réévaluer l'état cognitif à <span class=\"kw-chiffre\">6 mois</span> (la confusion peut révéler un <span class=\"kw-def\">syndrome démentiel</span> débutant).</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/etat-confusionnel-troubles-conscience","label":"Pedia-univ — Etat confusionnel troubles conscience"},{"href":"https://www.cen-neurologie.fr/second-cycle/confusion-troubles-cognitifs-et-demence","label":"Collège (CEN) — Confusion troubles cognitifs et demence"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Confusion / trouble de conscience aigu — Urgence diagnostique ET thérapeutique — après mise en condition (ABCDE, constantes, glycémie capillaire)","detail":"<h4>CAT — confusion / trouble de conscience aigu — Orientation diagnostique (adulte & enfant)</h4>","branches":[{"to":"t-tdm","label":"Signe de localisation · TC même mineur · chute peu claire · anticoagulant · installation brutale","color":"red"},{"to":"q-fievre","label":"Pas de signe de localisation → étape suivante","color":"blue"}]},{"id":"t-tdm","kind":"terminal","label":"TDM cérébrale en urgence","color":"red","detail":"<h4>Indications</h4><ul><li><span class=\"kw-alerte\">Signe de localisation</span> neurologique</li><li><span class=\"kw-etio\">Traumatisme crânien</span> même mineur ou <span class=\"kw-alerte\">chute peu claire</span></li><li>Traitement <span class=\"kw-ttt\">anticoagulant</span></li><li><span class=\"kw-clinique\">Confusion</span> d'installation brutale ; suspicion d'<span class=\"kw-etio\">hémorragie méningée</span></li></ul><h4>Objectif</h4><ul><li>Rechercher un <span class=\"kw-etio\">hématome intracrânien</span>, un <span class=\"kw-etio\">AVC</span>, un <span class=\"kw-etio\">processus expansif</span> ou une <span class=\"kw-etio\">hémorragie méningée</span></li></ul><h4>Renvoi</h4><ul><li>Item 340 (<span class=\"kw-alerte\">AVC</span>) · Item 341 (Hémorragie méningée)</li></ul>"},{"id":"q-fievre","kind":"decision","label":"Fièvre et/ou syndrome méningé ? — Toute confusion fébrile fait évoquer une infection du SNC","branches":[{"to":"t-pl","label":"Oui — fièvre sans point d'appel ou syndrome méningé","color":"red"},{"to":"q-postcritique","label":"Non","color":"blue"}]},{"id":"t-pl","kind":"terminal","label":"Ponction lombaire en urgence","color":"red","detail":"<h4>Indications</h4><ul><li><span class=\"kw-alerte\">Fièvre sans autre point d'appel</span> <span class=\"kw-etio\">infectieux</span></li><li><span class=\"kw-alerte\">Syndrome méningé</span> ; suspicion d'<span class=\"kw-etio\">hémorragie méningée</span></li></ul><h4>Séquence</h4><ul><li>La <span class=\"kw-imagerie\">ponction lombaire</span> est réalisée <strong>après la <span class=\"kw-imagerie\">TDM</span> cérébrale</strong> s'il existe un <span class=\"kw-alerte\">signe de localisation</span> (éliminer une <span class=\"kw-alerte\">HTIC</span>)</li></ul><h4>Cause recherchée</h4><ul><li><span class=\"kw-etio\">Méningite</span>, <span class=\"kw-etio\">méningo-encéphalite</span> (dont herpétique)</li></ul><h4>Renvoi</h4><ul><li>Item 151 (Méningite - méningoencéphalite)</li></ul>"},{"id":"q-postcritique","kind":"decision","label":"Contexte évocateur de crise / épilepsie ? — Épilepsie connue, mouvements convulsifs, confusion post-critique prolongée","branches":[{"to":"t-eeg","label":"Oui — suspicion de confusion post-critique","color":"amber"},{"to":"q-metab","label":"Non","color":"blue"}]},{"id":"t-eeg","kind":"terminal","label":"EEG en urgence","color":"amber","detail":"<h4>Indications</h4><ul><li>Suspicion de <span class=\"kw-etio\">confusion post-critique</span> d'une <span class=\"kw-def\">épilepsie</span></li><li><span class=\"kw-def\">Dépistage</span> d'un <span class=\"kw-alerte\">état de mal non convulsivant</span> / d'<span class=\"kw-etio\">épilepsies infracliniques</span> (bilan étiologique négatif)</li></ul><h4>Résultat</h4><ul><li><span class=\"kw-bio\">Ralentissement global</span> de l'activité électrique (non spécifique) ; recherche d'anomalies paroxystiques</li></ul><h4>Renvoi</h4><ul><li>Item 105 (Épilepsies)</li></ul>"},{"id":"q-metab","kind":"decision","label":"Cause métabolique ou toxique évidente ? — Hypoglycémie capillaire · sevrage alcoolique · dysnatrémie · prise médicamenteuse","branches":[{"to":"t-correction","label":"Oui — hypoglycémie, sevrage alcoolique, trouble hydro-électrolytique","color":"red"},{"to":"t-bilan","label":"Non — pas de cause évidente","color":"amber"}]},{"id":"t-correction","kind":"terminal","label":"Correction urgente de la cause","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hypoglycémie</span> → resucrage immédiat</li><li><span class=\"kw-alerte\">Sevrage alcoolique sévère</span> (delirium tremens) → prise en charge spécialisée + <span class=\"kw-ttt\">vitamine B1</span></li><li><span class=\"kw-etio\">Trouble hydro-électrolytique</span> (<span class=\"kw-bio\">dysnatrémie</span>, <span class=\"kw-bio\">hypercalcémie</span>) → correction adaptée</li></ul><h4>Principe</h4><ul><li>Le <span class=\"kw-ttt\">traitement étiologique</span> est souvent le seul traitement nécessaire à la guérison du <span class=\"kw-def\">syndrome confusionnel</span></li></ul><h4>Renvoi</h4><ul><li>Item 240 (Hypoglycémie) · Item 76 (Addiction à l'alcool)</li></ul>"},{"id":"t-bilan","kind":"terminal","label":"Bilan biologique de 1ère intention, puis imagerie en 2nde intention","color":"amber","detail":"<h4>Bilan de <span class=\"kw-chiffre\">1ère intention</span></h4><ul><li><span class=\"kw-bio\">SaO2</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">protides totaux</span>, <span class=\"kw-bio\">bandelette urinaire</span></li><li><span class=\"kw-clinique\">ECG</span> ; le CEN ajoute <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-imagerie\">radiographie thoracique</span></li></ul><h4>2nde intention</h4><ul><li>Si bilan négatif avec <span class=\"kw-clinique\">confusion</span> persistante : <span class=\"kw-imagerie\">TDM cérébrale</span>, puis <span class=\"kw-bio\">EEG</span> (épilepsie infraclinique) ± <span class=\"kw-imagerie\">ponction lombaire</span></li></ul><h4>Sujet âgé</h4><ul><li>Traquer les <span class=\"kw-etio\">causes non neurologiques</span> réversibles : <span class=\"kw-clinique\">fécalome</span>, <span class=\"kw-clinique\">globe vésical</span>, douleur, <span class=\"kw-etio\">infection</span>, iatrogénie</li></ul><h4>Renvoi</h4><ul><li>Item 108 (Confusion, démence du sujet âgé)</li></ul>"}]},"cards":[{"i":"00c75e18260d","n":343,"o":"343-1","u":"Définition","t":"Connaître la définition du syndrome confusionnel","q":"Comment définir le syndrome confusionnel sur le plan clinique ?","a":"<p>Le syndrome confusionnel (ou <strong>délirium</strong>) est une altération <strong>modérée de la vigilance</strong> conduisant à une désorganisation globale de la pensée et à un dysfonctionnement de toutes les fonctions cognitives. Il s'agit d'un trouble <strong>attentionnel sévère</strong>, d'installation <strong>aiguë ou subaiguë</strong> et au caractère <strong>fluctuant</strong>.</p>"},{"i":"a291979fb5ce","n":343,"o":"343-1","u":"Définition","t":"Connaître la définition du syndrome confusionnel","q":"Quels sont les critères C, D et E du DSM-5 pour le diagnostic de syndrome confusionnel ?","a":"<ul><li><strong>Critère C (Cognition)</strong> : Existence d'une autre perturbation cognitive (mémoire, orientation, langage, habiletés visuo-spatiales ou perceptions).</li><li><strong>Critère D (Exclusion)</strong> : Les critères A et C ne sont pas mieux expliqués par un trouble neurocognitif préexistant et ne surviennent pas dans un contexte de vigilance très réduite (coma).</li><li><strong>Critère E (Étiologie)</strong> : La perturbation est la conséquence directe d'une affection médicale, d'une intoxication, d'un sevrage (drogue ou médicament), d'une exposition à un toxique, ou de causes multiples.</li></ul>"},{"i":"aa13452ed297","n":343,"o":"343-1","u":"Définition","t":"Connaître la définition du syndrome confusionnel","q":"Quel est le critère A du DSM-5 pour le diagnostic de syndrome confusionnel ?","a":"<p>Le critère A est une <strong>perturbation de l'attention</strong> (diminution de la capacité à diriger, focaliser, soutenir et déplacer son attention) et de l'orientation. Elle s'évalue par des tests d'orientation spatio-temporelle et des épreuves attentionnelles (ex: jours de la semaine à l'envers).</p>"},{"i":"bf4a0800c393","n":343,"o":"343-1","u":"Définition","t":"Connaître la définition du syndrome confusionnel","q":"Quel est le critère B du DSM-5 concernant l'installation et l'évolution du syndrome confusionnel ?","a":"<p>Le critère B stipule une installation sur un <strong>temps court</strong> (quelques heures à quelques jours), une <strong>fluctuation</strong> de la sévérité au long de la journée et une <strong>rupture avec l'état antérieur</strong>, établie par l'interrogatoire d'un proche. Il mentionne aussi l'identification des formes hypo- et hyperactives.</p>"},{"i":"352f25c1f80b","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Quelles sont les mesures générales non pharmacologiques à privilégier chez l'adulte présentant un syndrome confusionnel ?","a":"<ul><li>Retirer les traitements <strong>non indispensables ou redondants</strong>, surtout les psychotropes (sans sevrage brutal).</li><li>Maintenir l'<strong>hydratation et la nutrition</strong>.</li><li>Assurer un <strong>environnement calme et sécurisant</strong> (chambre individuelle, lumière tamisée).</li><li>Lutter contre l'isolement sensoriel et restaurer les <strong>repères spatio-temporels</strong>.</li><li>Surveiller fréquemment les <strong>constantes vitales et la conscience</strong>.</li><li>Évaluer et traiter la <strong>douleur</strong>.</li></ul>"},{"i":"41397f4569b4","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Quel est le principe majeur du traitement étiologique d'un syndrome confusionnel chez l'adulte ?","a":"<p>Le principe majeur est la <strong>priorité absolue au traitement de la cause</strong>, car seul le traitement étiologique permet la guérison.</p>"},{"i":"4f5560e67e0f","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Comment prendre en charge un délire ou des hallucinations avec agitation compromettant la sécurité chez un patient adulte confus ?","a":"<p>On utilise un <strong>neuroleptique atypique à faible dose par voie orale</strong> (ex : rispéridone ou olanzapine orodispersible). Les formes injectables sont à éviter, et le tiapride IM est réservé en dernier recours. Tout délire ne justifie pas un traitement médicamenteux.</p>"},{"i":"76380ed24c1f","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Quelle est la première étape de la prise en charge d'un syndrome confusionnel chez l'adulte ?","a":"<p>La première étape est d'<strong>évaluer le retentissement vital</strong> à court terme (constantes vitales) et de <strong>traiter immédiatement les troubles vitaux</strong> (ex : état de choc, hypothermie).</p>"},{"i":"d0abaee21f7b","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Quand et comment traiter symptomatiquement une anxiété majeure chez un patient adulte confus ?","a":"<p>Le traitement symptomatique est un recours rare et de dernier recours. En cas d'anxiété majeure, on utilise des <strong>benzodiazépines à demi-vie courte et à faible dose par voie orale</strong> (ex : oxazépam ou alprazolam). L'hydroxizine, le cyamémazine et l'halopéridol doivent être évités.</p>"},{"i":"f3a6fa99fb05","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Quels sont les trois pièges thérapeutiques à éviter dans la prise en charge d'un syndrome confusionnel ?","a":"<ul><li>Éviter les <strong>anticholinergiques chez le confus âgé</strong>.</li><li>Ne jamais <strong>sevrer brutalement un psychotrope ancien</strong>, car le sevrage est confusiogène.</li><li>Réserver la <strong>contention physique au dernier recours</strong>, en raison de son effet aggravant sur l'agitation.</li></ul>"},{"i":"f8916093ed3e","n":343,"o":"343-10","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge d’un syndrome confusionnel chez l’adulte et chez l’enfant selon l’étiologie","q":"Quelles sont les spécificités de la prise en charge d'un syndrome confusionnel chez l'enfant ?","a":"<ul><li>La prise en charge est hospitalière et hiérarchisée, avec recherche de <strong>signes de gravité menaçant le pronostic vital</strong>.</li><li>Application de la séquence <strong>« ABCDE »</strong> (Airways, Breathing, Circulation, Disability, Exposure).</li><li><strong>Libération des voies aériennes</strong>, <strong>oxygénothérapie</strong> &plusmn; ventilation mécanique si Glasgow &lt; 8.</li><li>Objectifs de <strong>FC et PA adaptés à l'âge</strong>.</li><li>Vérification de la <strong>glycémie capillaire et bandelette urinaire</strong>.</li><li>Prévention de l'<strong>HTIC</strong> (décubitus dorsal à 30°, normoxie et normocapnie).</li></ul>"},{"i":"1835d30d4ffa","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Comment est établi le diagnostic du syndrome confusionnel chez l'adulte ?","a":"<p>Le diagnostic du syndrome confusionnel est <strong>exclusivement clinique</strong>. Il est essentiel de rechercher une <strong>rupture avec l'état antérieur</strong> du patient en interrogeant systématiquement un proche.</p>"},{"i":"1ce369e92b06","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Quels troubles du comportement et manifestations associées peuvent être observés lors d'un syndrome confusionnel chez l'adulte ?","a":"<ul><li><strong>Troubles du comportement</strong>: perplexité anxieuse, agitation, agressivité (forme agitée) ou apathie, somnolence (forme ralentie).</li><li><strong>Délire onirique</strong> (plus rarement structuré) et <strong>hallucinations</strong> (le plus souvent visuelles).</li><li><strong>Autres manifestations</strong>: labilité de l'humeur, inversion du cycle veille-sommeil, et signes somatiques non spécifiques (myoclonies, tremblement, astérixis).</li><li><strong>Amnésie lacunaire</strong> couvrant toute la durée de l'épisode.</li></ul>"},{"i":"560b2e4513ae","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Quels sont les principaux axes sémiologiques du syndrome confusionnel chez l'adulte ?","a":"<ul><li><strong>Périodicité</strong>: installation <strong>brusque ou rapidement progressive</strong> (minutes, heures, jours), <strong>fluctuation</strong> de la sévérité au long de la journée, et <strong>recrudescence vespérale ou nocturne</strong>.</li><li><strong>Attention & conscience</strong>: <strong>désorientation temporo-spatiale constante</strong>, difficulté à maintenir l'attention, distractibilité.</li><li><strong>Mémoire</strong>: trouble de la <strong>mémoire à court terme</strong> et de l'encodage.</li><li><strong>Langage</strong>: langage spontané <strong>décousu et incohérent</strong>.</li><li><strong>Pensée</strong>: <strong>désorganisation de la pensée</strong>, altération du raisonnement et du jugement.</li></ul>"},{"i":"6f10d7062a67","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Comment interprète-t-on le score de Glasgow pédiatrique pour un état confusionnel ?","a":"<ul><li>Un score maximal de <strong>15</strong> indique un état de conscience normal.</li><li>Un score <strong>inférieur ou égal à 8</strong> est un <strong>coma sévère</strong>, nécessitant une prise en charge urgente, la libération des voies aériennes et la discussion d'une intubation.</li><li>Un score minimal de <strong>3</strong> indique un <strong>coma profond</strong> avec un mauvais pronostic.</li></ul>"},{"i":"7db261038c49","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Comment distingue-t-on l'état confusionnel, l'éveil et le coma chez l'enfant ?","a":"<ul><li><strong>Éveil</strong>: Commandé par la formation réticulée, permet la restauration et le maintien de la vigilance.</li><li><strong>État confusionnel</strong>: Altération aiguë ou subaiguë de la conscience, avec ou sans troubles authentiques de la vigilance.</li><li><strong>Coma</strong>: Altération aiguë ou subaiguë définie par l'<strong>absence d'éveil spontané ou provoqué</strong>, prolongée au-delà d'<strong>1 heure</strong>.</li></ul>"},{"i":"82e203626d5a","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Quelle est la principale méthode d'évaluation de la conscience chez l'enfant et quels signes de gravité faut-il rechercher ?","a":"<p>L'évaluation pédiatrique repose sur un <strong>score de Glasgow adapté à l'âge</strong>. Il faut rechercher systématiquement des <strong>signes de gravité menaçant le pronostic vital</strong> : défaillance hémodynamique, respiratoire ou neurologique, et signes d'hypertension intracrânienne.</p>"},{"i":"b92fed5b4e84","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Quelles sont les particularités cliniques du syndrome confusionnel chez le patient âgé?","a":"<p>Chez le patient âgé, il faut évoquer un syndrome confusionnel devant toute <strong>modification rapide comportementale ou cognitive</strong> ou toute <strong>inversion du rythme nycthéméral</strong>.</p>"},{"i":"f61be9373987","n":343,"o":"343-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique du syndrome confusionnel chez l’adulte et particularités chez l’enfant","q":"Quels sont les critères diagnostiques du syndrome confusionnel selon le DSM-5 ?","a":"<p>Les critères DSM-5 pour le syndrome confusionnel sont les suivants :</p><ul><li><strong>A</strong>: Perturbation de l'attention et de l'orientation.</li><li><strong>B</strong>: Installation rapide et fluctuante.</li><li><strong>C</strong>: Autre perturbation cognitive.</li><li><strong>D</strong>: Exclusion d'un trouble neurocognitif préexistant et d'un coma.</li><li><strong>E</strong>: Cause médicale, toxique ou sevrage identifiée.</li></ul>"},{"i":"530cec79e2e1","n":343,"o":"343-4","u":"Diagnostic positif","t":"Connaître les trois formes cliniques du syndrome confusionnel","q":"Quelle est la caractéristique principale du syndrome confusionnel dans sa forme confuso-onirique (hyperactive) et quels sont les risques associés ?","a":"<p>La forme confuso-onirique du syndrome confusionnel se caractérise par une <strong>agitation psychomotrice</strong> au premier plan, des <strong>délires oniriques</strong> et des <strong>troubles végétatifs</strong> (hypersudation, tachycardie). Le risque majeur est celui d'une <strong>iatrogénie</strong> par surtraitement sédatif.</p>"},{"i":"bbd6fae7a891","n":343,"o":"343-4","u":"Diagnostic positif","t":"Connaître les trois formes cliniques du syndrome confusionnel","q":"Comment se manifeste le syndrome confusionnel dans sa forme stuporeuse (hypoactive) et pourquoi cette forme est-elle si importante à reconnaître ?","a":"<p>La forme stuporeuse (hypoactive) du syndrome confusionnel se manifeste par une <strong>apathie</strong>, un <strong>repli sur soi</strong>, un <strong>ralentissement psychomoteur</strong> et de la <strong>somnolence</strong>. Elle est fondamentale à reconnaître car c'est la <strong>plus fréquente</strong>, de <strong>plus mauvais pronostic</strong> et la <strong>plus sous-diagnostiquée</strong>, souvent confondue avec une dépression ou un trouble neurocognitif majeur.</p>"},{"i":"ce705db1238c","n":343,"o":"343-4","u":"Diagnostic positif","t":"Connaître les trois formes cliniques du syndrome confusionnel","q":"Comment se présente la forme mixte du syndrome confusionnel ?","a":"<p>La forme mixte du syndrome confusionnel se caractérise par une <strong>alternance irrégulière et imprévisible</strong> des états observés dans les formes confuso-onirique (hyperactive) et stuporeuse (hypoactive).</p>"},{"i":"202472c2c762","n":343,"o":"343-6","u":"Identifier une urgence","t":"Connaître les situations nécessitant une prise en charge en urgence","q":"Quelles sont les urgences métaboliques ou toxiques nécessitant une prise en charge immédiate devant un état confusionnel ?","a":"<p>Les urgences métaboliques ou toxiques imposant une correction urgente sont :</p><ul><li>l'<strong>hypoglycémie</strong> ;</li><li>l'<strong>hyperthermie</strong> ;</li><li>l'<strong>hypothermie</strong> ;</li><li>le <strong>sevrage alcoolique sévère</strong> (delirium tremens, urgence vitale) ;</li><li>une <strong>intoxication aiguë</strong>.</li></ul>"},{"i":"31716c5e5847","n":343,"o":"343-6","u":"Identifier une urgence","t":"Connaître les situations nécessitant une prise en charge en urgence","q":"Quels sont les dangers spécifiques d'un état confusionnel, outre sa cause sous-jacente ?","a":"<p>Outre la pathologie causale (ex: diabète décompensé, hémorragie méningée), la confusion elle-même est dangereuse par ses conséquences :</p><ul><li><strong>désordres comportementaux majeurs</strong> (agitation, agressivité) ;</li><li><strong>déshydratation</strong> ;</li><li><strong>chutes</strong>.</li></ul>"},{"i":"4aebc5993576","n":343,"o":"343-6","u":"Identifier une urgence","t":"Connaître les situations nécessitant une prise en charge en urgence","q":"Pourquoi un syndrome confusionnel est-il une urgence diagnostique et thérapeutique ?","a":"<p>Un syndrome confusionnel est une urgence car la <strong>cause sous-jacente est souvent grave et potentiellement létale</strong>, et la confusion elle-même représente un <strong>danger pour le patient</strong>.</p>"},{"i":"ba9ab24a823e","n":343,"o":"343-6","u":"Identifier une urgence","t":"Connaître les situations nécessitant une prise en charge en urgence","q":"Face à un syndrome confusionnel, quelle situation impose une TDM cérébrale en urgence ?","a":"<p>Une TDM cérébrale est indiquée en urgence devant un syndrome confusionnel si :</p><ul><li>présence d'un <strong>signe de localisation neurologique</strong> (suspicion d'AVC, hémorragie méningée, hématome, processus expansif) ;</li><li>antécédent de <strong>traumatisme crânien</strong> (même mineur) ou de <strong>chute inexpliquée</strong> (recherche d'hématome intracrânien).</li></ul>"},{"i":"dab2019fb8b8","n":343,"o":"343-6","u":"Identifier une urgence","t":"Connaître les situations nécessitant une prise en charge en urgence","q":"Quelle exploration doit être envisagée en urgence en cas de suspicion de confusion post-critique d'épilepsie et pourquoi ?","a":"<p>Il convient de réaliser une <strong>EEG en urgence</strong> pour rechercher un <strong>état de mal non convulsivant</strong>, qui peut se manifester par un état confusionnel.</p>"},{"i":"eccadf5cbd70","n":343,"o":"343-6","u":"Identifier une urgence","t":"Connaître les situations nécessitant une prise en charge en urgence","q":"Quelle exploration diagnostique doit être réalisée en urgence en cas de fièvre sans point d'appel ou de syndrome méningé chez un patient confus ?","a":"<p>Une <strong>ponction lombaire</strong> doit être réalisée en urgence en cas de fièvre sans point d'appel ou de syndrome méningé chez un patient confus, idéalement après élimination d'une contre-indication par TDM si signes de localisation neurologique.</p>"},{"i":"019ace9e2671","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quelles sont les causes simples et facilement réversibles de syndrome confusionnel à privilégier chez le sujet âgé ?","a":"<p>Chez le sujet âgé, il faut privilégier la recherche de causes simples et facilement réversibles de syndrome confusionnel, souvent non neurologiques :</p><ul><li>Le <strong>fécalome</strong></li><li>Le <strong>globe vésical</strong> (rétention aiguë d'urine)</li><li>La <strong>douleur</strong></li><li>Les <strong>troubles neurosensoriels</strong></li></ul>"},{"i":"08d52591955a","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quel piège diagnostique majeur doit être évoqué face à un syndrome confusionnel chez le nourrisson ?","a":"<p>Le piège diagnostique majeur chez le nourrisson présentant un syndrome confusionnel avec peu de lésions externes est le <strong>traumatisme crânien infligé</strong>, notamment le <strong>syndrome du bébé secoué</strong>, qui doit être systématiquement évoqué.</p>"},{"i":"23ac529ee679","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quelles sont les cinq grandes catégories étiologiques du syndrome confusionnel chez l'adulte ?","a":"<p>Les cinq grandes catégories étiologiques du syndrome confusionnel chez l'adulte sont :</p><ul><li>Les causes <strong>toxiques</strong> (alcool, drogues, médicaments)</li><li>Les causes <strong>métaboliques</strong> (hydro-électrolytiques, glycémie, endocrinopathies, insuffisances d'organe, carences vitaminiques)</li><li>Les causes <strong>neurologiques</strong> (hémorragie méningée, infections neuroméningées, processus expansifs, traumatismes crâniens, infarctus cérébraux, épilepsie)</li><li>Les causes <strong>infectieuses & fièvre</strong> (urinaires, pulmonaires, toute fièvre)</li><li>Les <strong>autres causes</strong> (hypothermie, hypoxie/anoxie cérébrale, post-opératoire)</li></ul>"},{"i":"350bb655a094","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quelles sont les principales étiologies du syndrome confusionnel chez l'enfant ?","a":"<p>Les principales étiologies du syndrome confusionnel chez l'enfant se répartissent en plusieurs catégories :</p><ul><li><strong>Défaillance vitale</strong> : insuffisance respiratoire aiguë hypercapnique ou hypoxique, état de choc, crise hypertensive maligne</li><li><strong>Désordres métaboliques</strong> : hypoglycémie, dysnatrémie, acidocétose</li><li><strong>Intoxications</strong> : <strong>CO</strong>, <strong>paracétamol</strong> (avec deux pics de fréquence : enfant &lt; 5 ans et adolescent)</li><li><strong>Causes neurologiques</strong> : traumatisme crânien (toujours évoquer le <strong>TC infligé</strong> chez le nourrisson), infections neuroméningées, état de mal épileptique, tumeurs cérébrales, AVC</li><li><strong>Autres</strong> : anomalies héréditaires du métabolisme, pathologies de système</li></ul>"},{"i":"715e54999fc3","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quels sont les mécanismes métaboliques pouvant causer un syndrome confusionnel chez l'adulte ?","a":"<p>Les mécanismes métaboliques pouvant causer un syndrome confusionnel chez l'adulte sont :</p><ul><li><strong>Désordres hydro-électrolytiques</strong> : hyper/hyponatrémie, hypokaliémie, hypercalcémie, déshydratation</li><li>Troubles de la <strong>glycémie</strong> : hypoglycémie</li><li><strong>Endocrinopathies</strong> : décompensation d'un diabète, insuffisance surrénale aiguë, hypothyroïdie, insuffisance antéhypophysaire aiguë</li><li><strong>Insuffisances d'organe</strong> : rénale, hépatique, cardio-respiratoire, décompensées ou aiguës</li><li><strong>Carences vitaminiques</strong> : B1 (Gayet-Wernicke, Korsakoff), B3 (pellagre), Marchiafava-Bignami, B9/B12</li></ul>"},{"i":"7a0f5939a9d7","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quels sont les principaux facteurs de risque généraux du syndrome confusionnel chez l'adulte ?","a":"<p>Les principaux facteurs de risque du syndrome confusionnel chez l'adulte sont :</p><ul><li><strong>Âge ≥ 80 ans</strong></li><li><strong>Antécédents de confusion</strong>, en particulier postopératoire</li><li><strong>Trouble neurocognitif</strong> ou troubles cognitifs sous-jacents</li><li><strong>Immobilisation</strong>, aggravée par la contention physique</li><li><strong>Déficit sensoriel</strong> (visuel ou auditif)</li><li><strong>Comorbidités multiples</strong></li><li><strong>Dénutrition</strong></li><li><strong>Polymédication</strong></li><li><strong>Troubles de l'humeur</strong></li></ul>"},{"i":"a16246011ad9","n":343,"o":"343-7","u":"Étiologies","t":"Connaître les principales étiologies et les principaux facteurs de risque du syndrome confusionnel chez l’adulte et chez l’enfant","q":"Quelles sont les étiologies toxiques à rechercher en cas de syndrome confusionnel chez l'adulte ?","a":"<p>Les étiologies toxiques à rechercher en cas de syndrome confusionnel chez l'adulte incluent :</p><ul><li><strong>L'alcool</strong> : ivresse aiguë ou sevrage</li><li>Les <strong>drogues</strong> : héroïne, cocaïne</li><li>Les <strong>toxiques industriels</strong> : pesticides, solvants, intoxication au <strong>CO</strong></li><li>Les <strong>médicaments</strong> : psychotropes (BZD, antidépresseurs, neuroleptiques, lithium, antiépileptiques, opioïdes), anti-parkinsoniens, anticholinergiques. Le <strong>sevrage brutal</strong> d'un psychotrope est également confusiogène. Chez le sujet âgé, l'insuffisant hépatique ou rénal, presque tous les médicaments sont incriminables.</li></ul>"},{"i":"15d6a36a9ab0","n":343,"o":"343-8","u":"Examens complémentaires","t":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","q":"Quel est le rationnel du bilan biologique de première intention devant un syndrome confusionnel, en l'absence de cause évidente ?","a":"<p>Le bilan biologique de première intention devant un syndrome confusionnel est systématique lorsque aucune cause évidente n'a été identifiée. Chaque examen vise une <strong>étiologie précise</strong>.</p>"},{"i":"462e001de4d9","n":343,"o":"343-8","u":"Examens complémentaires","t":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","q":"Quelle est l'utilité de la NFS et de la CRP dans le bilan de première intention d'un syndrome confusionnel ?","a":"<p>La <strong>NFS</strong> (Numération Formule Sanguine) et la <strong>CRP</strong> (C-Réactive Protéine) sont utilisées pour rechercher une <strong>cause infectieuse ou inflammatoire</strong>.</p>"},{"i":"47d78bcc2256","n":343,"o":"343-8","u":"Examens complémentaires","t":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","q":"Quelle étiologie est recherchée par la glycémie et la calcémie dans le cadre d'un syndrome confusionnel ?","a":"<ul><li>La <strong>glycémie</strong> recherche une <strong>hypoglycémie</strong> ou une <strong>décompensation diabétique</strong>.</li><li>La <strong>calcémie</strong> recherche une <strong>hyper- ou une hypocalcémie</strong>.</li></ul>"},{"i":"60187fea9211","n":343,"o":"343-8","u":"Examens complémentaires","t":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","q":"Pourquoi réalise-t-on un ECG devant un syndrome confusionnel ?","a":"<p>L'<strong>ECG</strong> est réalisé pour rechercher une <strong>ischémie myocardique</strong> ou un <strong>trouble du rythme cardiaque</strong>.</p>"},{"i":"d73b23f74718","n":343,"o":"343-8","u":"Examens complémentaires","t":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","q":"Quels examens complémentaires sont ajoutés au bilan de première intention en neurologie de l'interne, et quelles étiologies ciblent-ils face à un syndrome confusionnel ?","a":"<ul><li>Le <strong>bilan hépatique</strong> (ALAT, ASAT, PAL, GGT, Bili) cible une <strong>encéphalopathie hépatique</strong>.</li><li>Le <strong>bilan d'hémostase</strong> (TP, TCA) cible une suspicion d'<strong>hématome intracrânien</strong>.</li><li>La <strong>radiographie thoracique</strong> recherche une <strong>cause infectieuse ou inflammatoire pulmonaire</strong>.</li></ul>"},{"i":"f73a74d34769","n":343,"o":"343-8","u":"Examens complémentaires","t":"Connaître le bilan biologique de première intention devant un syndrome confusionnel","q":"Quels sont les éléments du bilan biologique minimum de première intention à réaliser devant un syndrome confusionnel ?","a":"<ul><li><strong>SaO2</strong></li><li><strong>NFS</strong></li><li><strong>CRP</strong></li><li><strong>Créatininémie</strong></li><li><strong>Ionogramme sanguin</strong></li><li><strong>Calcémie</strong></li><li><strong>Glycémie</strong></li><li><strong>Protides totaux</strong></li><li><strong>Bandelette urinaire</strong></li><li><strong>ECG</strong> (bien que ce ne soit pas un examen biologique strict, il fait partie du bilan initial systématique mentionné).</li></ul>"}]};